const currentBooking=()=>state.bookings.find(b=>b.id===state.selected)||state.bookings[0];
const driver=()=>people[state.driver];
function notify(role,title,text,id=state.selected){state.notifications[role].unshift({title,text,id,read:false})}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function closeModal(){$('#overlay').innerHTML='';$('#overlay').className='';choiceCallback=null}
function modal(title,content,buttons='',sheet=false){$('#overlay').className=sheet?'sheet-overlay':'';$('#overlay').innerHTML=`<section class="dialog ${sheet?'sheet':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}">${sheet?'<button class="handle" data-action="close" aria-label="Close sheet"></button>':''}<h2>${title}</h2>${content}<div class="actions">${buttons||btn('Close','close','','outline')}</div></section>`;setTimeout(()=>$('#overlay button, #overlay input')?.focus({preventScroll:true}),50)}
function confirmDialog(title,text,a,value='',positive='Confirm'){modal(title,`<p>${text}</p>`,btn('Go back','close','','outline')+btn(positive,a,value))}
function header(title,extra=''){return `<header class="header">${ib('back','back','','Back')}<h2>${title}</h2>${extra}</header>`}
function nav(active){return `<nav class="nav" aria-label="App navigation">${[['home','home','Home'],['bookings','calendar',state.role==='driver'?'Booking':'Bookings'],['messages','message',state.role==='driver'?'Message':'Messages'],['profile','user','Profile']].map(([id,i,l])=>`<button class="${id===active?'active':''}" ${action('go',id)}><span class="navicon">${icon(i)}</span>${l}</button>`).join('')}</nav>`}
function page(title,body,options={}){return header(title,options.extra||'')+`<div class="scroll ${options.gray?'pale':''} ${options.pad===false?'':'pad'}">${body}</div>`+(options.bottom?`<div class="bottom-action">${options.bottom}</div>`:'')+(options.nav?nav(options.nav):'')}
function go(screen,remember=true){if(remember)history.push(state.screen);state.screen=screen;closeModal();fullMap=false;mapCollapsed=false;render();requestHomeLocation()}
function requestHomeLocation(){
  if(state.screen!=='home')return;
  state.locationPrompted??={};
  if(state.locationPrompted[state.role])return;
  state.locationPrompted[state.role]=true;
  modal('Allow location access?','<p>HireMyDriver uses your location for nearby drivers, pickup locations, and trip maps.</p>',btn('Not now','close','','outline')+btn('Allow','allow-location'));
}
function back(){closeModal();state.screen=history.pop()||'home';fullMap=false;render()}
function setRole(role){state.role=role;state.tab=role==='driver'?'Requests':'All';go('home');}
function route(b){return `<div class="route">${[b.pickup,...b.destinations].map((p,i)=>`<div class="route-point">${esc(p|| (i?'Choose destination':'Choose pickup'))}<small>${i?'Destination '+i:'Pickup'}</small></div>`).join('')}</div>`}
function userRow(b,customer=false){const d=people[b.driver];return `<div class="row">${img(customer?'mika':d.photo)}<div class="grow"><b>${esc(customer?state.profile.name:d.name)}</b><p class="muted small-text" style="margin:5px 0">${customer?esc(state.profile.email):'★ '+d.rating+' · '+esc(b.vehicle)}</p></div></div>`}
function driverCard(d,i,recommended=false){return `<button class="card driver-card" ${action('driver',i)}>${img(d.photo)}<div class="grow"><b>${esc(d.name)}</b>${recommended?`<div class="rating" style="margin-top:4px">★ ${d.rating}</div>`:''}<p>${d.exp} years exp. · ${d.area}<br>${d.types.join(', ')}</p>${recommended?`<span class="distance">● ${d.km} km away</span>`:''}</div>${recommended?icon('chevron'):`<div class="right"><span class="rating">★ ${d.rating}</span><p style="color:#092335;font-weight:bold">₱${d.rate}/hr</p></div>`}</button>`}
function home(){if(state.role==='driver'){return `<div class="scroll pale"><div class="hero" style="height:210px">${img('background','hero-bg','')}<div class="hero-content"><div class="row between"><span>Good Morning,</span>${ib('bell','go','notifications','Notifications')}</div><h2>${esc(people[0].name)}</h2><span class="badge" style="background:#ffffff18;color:white">${icon('shield','verified')} Verified Driver</span></div></div><div class="pad" style="margin-top:-35px;position:relative"><div class="card row"><div class="grow"><h3 style="margin:0 0 5px">Availability</h3><small class="muted">${state.available?'🟢 You are available to receive new booking requests.':'You are currently unavailable.'}</small></div><button aria-label="Toggle availability" class="toggle ${state.available?'on':''}" ${action('availability')}></button></div><div class="card stats"><div><b class="orange">${state.bookings.filter(b=>b.status==='Pending').length}</b><small>Pending</small></div><div><b style="color:#159447">${state.bookings.filter(b=>b.status==='Completed').length}</b><small>Completed</small></div><div><b>4.9</b><small>Rating</small></div></div><div class="section-heading"><h3>Upcoming Booking</h3><button class="text-btn" ${action('booking-tab','Upcoming')}>View All</button></div>${state.bookings.filter(b=>b.status==='Accepted').slice(0,1).map(b=>bookingCard(b,true)).join('')||'<p class="helper">No upcoming bookings.</p>'}<div class="section-heading"><h3>New Booking Requests</h3><button class="text-btn" ${action('booking-tab','Requests')}>View All</button></div>${state.bookings.filter(b=>b.status==='Pending').slice(0,10).map(b=>bookingCard(b,true)).join('')||'<p class="helper">No new requests.</p>'}</div></div>${nav('home')}`}
return `<div class="scroll"><div class="hero">${img('img_home_car_bg','hero-bg','')}${img('driver','hero-person','Driver illustration')}<div class="hero-content"><div class="row between"><h2>Hello, ${esc(state.profile.name.split(' ')[0])}!</h2>${ib('bell','go','notifications','Notifications')}</div><p>Where do you need<br>a driver today?</p></div></div><div class="home-content"><button class="searchbox" ${action('go','popular')}>${icon('search')}<span class="grow">Search drivers</span>${icon('filter')}</button><button class="best-driver" ${action('go','best')}>${icon('car')}<span class="grow"><b>Find My Best Driver</b><small>Find a driver that fits your trip</small></span>${icon('chevron')}</button><div class="section-heading"><h3>Recommended for you</h3><button class="text-btn" ${action('go','recommended')}>See All</button></div>${people.map((d,i)=>({d,i})).sort((a,b)=>a.d.km-b.d.km).slice(0,5).map(({d,i})=>driverCard(d,i,true)).join('')}<div class="section-heading"><h3>Popular Drivers</h3><button class="text-btn" ${action('go','popular')}>See All</button></div>${people.map((d,i)=>driverCard(d,i)).join('')}</div></div>${nav('home')}`}
function bookingCard(b,driverView=state.role==='driver'){return `<article class="card"><button style="width:100%;text-align:left;padding:0" ${action('details',b.id)}><div class="row between"><b>${driverView?esc(state.profile.name):esc(people[b.driver].name)}</b><span class="badge ${b.status==='Pending'?'pending':b.status==='Completed'?'green':''}">${esc(b.status)}</span></div><p class="helper">${esc(b.date)} · ${esc(b.time)} · ${b.hours} hours</p><div class="small-text">${esc(b.pickup)} → ${esc(b.destinations.at(-1))}</div></button><div class="actions">${btn('View Details','details',b.id,'outline small')}${!driverView&&b.status==='Pending'?btn('Cancel Booking','cancel',b.id,'outline small'):driverView&&b.status==='Pending'?btn('Accept','accept',b.id,'small'):''}</div>${driverView&&b.status==='Pending'?`<button class="text-btn" style="color:#687482;width:100%;margin-top:8px" ${action('decline',b.id)}>Decline</button>`:''}${b.status==='Completed'&&!driverView?`<div class="actions">${btn('Rebook Driver','rebook',b.id,'soft small')}${btn('Rate Driver','rate-booking',b.id,'outline small')}</div>`:''}</article>`}
function bookings(){const tabs=state.role==='driver'?['Requests','Upcoming','Completed']:['All','Pending','Accepted','Completed','Cancelled'];const match={All:['Pending','Accepted','On the way','Arrived','In Progress','Completed','Cancelled','Declined'],Accepted:['Accepted','On the way','Arrived','In Progress'],Requests:['Pending'],Pending:['Pending'],Upcoming:['Accepted','On the way','Arrived'],'In Progress':['In Progress'],Completed:['Completed'],Cancelled:['Cancelled','Declined']};const list=state.bookings.filter(b=>(match[state.tab]||[]).includes(b.status));return header(state.role==='driver'?'Bookings':'My Bookings')+`<div class="tabs">${tabs.map(t=>`<button class="${state.tab===t?'active':''}" ${action('booking-tab',t)}>${t}</button>`).join('')}</div><div class="scroll pale pad">${list.map(b=>bookingCard(b)).join('')||'<div class="empty">'+icon('calendar')+'<h3 style="margin-top:18px">No bookings here yet</h3><p>Your bookings will appear in this section.</p></div>'}</div>`+nav('bookings')}
function bookingDetails(readOnly=false){const b=currentBooking(),d=people[b.driver];return page(readOnly?'Trip Details':'Booking Details',`<div class="card row"><div class="date-tile"><strong>OCT</strong><b>${b.date.split('-')[2]}</b><small>${b.time}</small></div><div><p class="muted" style="margin:0 0 9px">Booking Status</p><span class="badge ${b.status==='Completed'?'green':''}">${b.status}</span><p class="helper" style="margin-bottom:0">Booking ID: <b>${b.id}</b></p></div></div><div class="card"><h3>${state.role==='driver'?'Customer':'Driver'} Information</h3>${userRow(b,state.role==='driver')}${state.role==='driver'?`<p class="small-text muted" style="margin:14px 0 0">${icon('phone')} ${esc(state.profile.phone)}<br>${icon('pin')} ${esc(state.profile.address)}</p>`:''}</div><div class="card">${route(b)}${btn('View Map','go',b.status==='Completed'?'history':'trip','soft small')}</div><div class="card"><h3>Booking Information</h3>${kv('Booking Type','By the Hour ('+b.hours+'h)')}${kv('Vehicle Type',b.vehicle)}${kv('Additional Notes',esc(b.notes||'No additional notes'))}${kv('Date & Time',b.date+' · '+b.time)}${kv('Payment Method','Cash')}${kv('Total Amount',`<strong class="total">${money(b.hours*d.rate)}</strong>`)}${b.extension?`<p class="small-text">Extension request: ${b.extension.status}<br>Additional time: ${b.extension.minutes} minutes</p>${state.role==='driver'&&b.extension.status==='Pending'?btn('Review extension on map →','go','extension','soft small'):''}`:''}</div>${b.status==='Completed'?'<div class="card" style="text-align:center;background:#eef9f2;color:#258854">'+icon('check')+'<h3 style="margin:12px 0 0">Booking completed</h3></div>':''}`,{gray:true,bottom:readOnly||['Completed','Cancelled','Declined'].includes(b.status)?'':state.role==='driver'?(b.status==='Pending'?`<div class="actions" style="margin:0">${btn('Decline','decline',b.id,'outline')}${btn('Accept Booking','accept',b.id)}</div>`:btn(b.status==='In Progress'?'Open Trip Map':'Open Pickup Map','go','trip')):`<div class="actions" style="margin:0">${btn('Track Trip','go','trip','outline')}${btn('Message Driver','go','chat')}</div>`})}
function book(){const f=state.form,d=driver();return page('Book Driver',`<div class="card">${userRow({driver:state.driver,vehicle:f.vehicle})}<p class="rating" style="margin:12px 0 0">${money(d.rate)} / hour</p></div><h3>Booking Details</h3><div class="fields-row">${field('Date','book-date',f.date,'date')}${field('Start Time','book-time',f.time,'time')}</div>${select('Duration','book-hours',[1,2,3,4,5,6,7,8,10,12].map(n=>n+' hours'),f.hours+' hours')}${pick('Pickup',f.pickup||'Choose pickup on map','picker','pickup')}${f.destinations.map((v,i)=>pick('Destination '+(i+1),v,'picker','destination-'+i)).join('')}${f.destinations.length===0?pick('Destination','Choose destination on map','picker','destination-0'):''}<button class="text-btn" ${action('add-stop')}>${icon('plus')} Add another destination</button>${select('Vehicle Type','book-vehicle',d.types,f.vehicle)}<label class="field"><span>Additional Notes (Optional)</span><textarea id="book-notes" placeholder="Anything your driver should know?">${esc(f.notes)}</textarea></label><div class="card">${kv('Estimated Fee',`<strong id="fee" class="total">${money(d.rate*f.hours)}</strong>`)}<small class="muted">Cash · ${money(d.rate)} × <span id="hours-caption">${f.hours}</span> hours</small></div>`,{bottom:btn('Confirm Booking','review-booking')})}
function saveBookingForm(){const f=state.form;f.date=$('#book-date')?.value||f.date;f.time=$('#book-time')?.value||f.time;f.hours=parseInt($('#book-hours')?.value)||f.hours;f.vehicle=$('#book-vehicle')?.value||f.vehicle;f.notes=$('#book-notes')?.value??f.notes}
function reviewBooking(){const f=state.form,d=driver();return page('Review Booking',`<h3>Driver Information</h3>${userRow({driver:state.driver,vehicle:f.vehicle})}<hr style="border:0;border-top:1px solid #eee;margin:24px 0"><h3>Your Route</h3>${route(f)}<h3>Booking Details</h3>${kv('Date',f.date)}${kv('Time',f.time)}${kv('Duration',f.hours+' hours')}${kv('Vehicle Type',f.vehicle)}${kv('Payment Method','Cash')}<div class="card" style="margin-top:22px">${kv('Total Estimated Fee',`<strong class="total">${money(f.hours*d.rate)}</strong>`)}</div>`,{bottom:btn('Send Booking Request','submit-booking')})}
function driverProfile(){const d=driver();return page('Driver Profile',`<div class="profile-top">${img(d.photo,'avatar big')}<h2>${d.name}</h2><p><span class="rating">${d.rating}</span> (${state.reviews.length} reviews)</p><p>${d.exp} years experience</p></div><p class="small-text">${icon('car')} &nbsp; ${d.types.join(' · ')}<br><br>Automatic · Manual<br><br>${icon('pin')} &nbsp; ${d.area} (Bohol), Tagbilaran (Bohol)</p><div class="stats" style="border-block:1px solid #eee;margin:23px 0"><div>${icon('shield','verified')}<small style="display:block;margin-top:8px">Verified</small></div><div>${icon('user')}<small style="display:block;margin-top:8px">Professional</small></div><div>${icon('star')}<small style="display:block;margin-top:8px">Highly Rated</small></div></div><h3>About Me</h3><p class="muted small-text">${d.bio}</p><h3 style="margin-top:25px">Registered Address</h3><p class="muted small-text">Poblacion, ${d.area}, Bohol</p><h3 style="margin-top:24px">${icon('clock')} ${money(d.rate)}/hr</h3><h3>Availability</h3><p class="muted small-text">Weekly schedule · Philippine time</p>${state.schedule.filter(s=>s.enabled).map(s=>`<div class="kv"><b>${s.day}</b><b>${s.start} – ${s.end}</b></div>`).join('')}<div class="section-heading"><h3>Driver Reviews</h3><button class="text-btn" ${action('go','reviews')}>See All</button></div>${reviewCards()}`,{bottom:btn('Book Now','new-booking')})}
function listDrivers(){const filtered=people.map((d,i)=>({d,i})).filter(({d})=>(state.filter.vehicle==='All'||d.types.includes(state.filter.vehicle))&&(state.filter.area==='All'||d.area===state.filter.area||['Sikatuna','Tagbilaran'].includes(state.filter.area))&&(state.filter.experience==='All'||(state.filter.experience==='5+ years'?d.exp>=5:state.filter.experience==='3–5 years'?d.exp>=3&&d.exp<=5:d.exp<=3)));if(state.screen==='recommended'||state.screen==='results')filtered.sort((a,b)=>a.d.km-b.d.km);else filtered.sort((a,b)=>Number(b.d.rating)-Number(a.d.rating));return page(state.screen==='recommended'?'Recommended for you':state.screen==='results'?'Your Driver Matches':'Popular Drivers',`<div class="row" style="margin-bottom:18px"><input id="driver-search" aria-label="Search drivers" class="searchbox" placeholder="Search drivers" style="color:#34465a">${ib('filter','go','filter','Filter drivers')}</div><div id="driver-list">${filtered.map(({d,i})=>driverCard(d,i,state.screen!=='popular')).join('')||'<p class="empty">No drivers match these filters. Try another vehicle or area.</p>'}</div>`,{gray:true,extra:ib('refresh','refresh','','Refresh drivers')})}
function filters(){return page('Filter Drivers',`<h3>Vehicle Type</h3>${chips(['All',...vehicles],state.filter.vehicle,'filter-vehicle')}<h3>Experience</h3>${chips(['All','1–3 years','3–5 years','5+ years'],state.filter.experience,'filter-experience')}${pick('Service Area',state.filter.area==='All'?'Select service area':state.filter.area,'areas','filter')}<button class="text-btn" style="width:100%" ${action('clear-filters')}>Clear All</button>`,{bottom:btn('Apply Filters','go','popular')})}
function chips(values,active,a){return `<div class="chipset">${values.map(v=>`<button class="chip ${Array.isArray(active)?active.includes(v)?'active':'':v===active?'active':''}" ${action(a,v)}>${esc(v)}</button>`).join('')}</div>`}
function best(){return page('Find My Best Driver',`<h3>Tell us what you need</h3><p class="muted small-text">Find a driver for your location, schedule, and travel needs.</p>${pick('Your location',state.bestArea||'Sikatuna (Bohol)','areas','best')}<div class="fields-row">${field('Date','best-date','2026-10-26','date')}${field('Start Time','best-time','08:00','time')}</div>${select('Duration','best-hours',['1 hour','2 hours','3 hours','4 hours','8 hours'],'3 hours')}${select('Vehicle Type','best-vehicle',vehicles,'SUV')}${select('Transmission','best-transmission',['Any','Automatic','Manual'],'Any')}`,{bottom:btn('Find My Best Driver','find-best')})}
function mapArt(showRoute=true){return `<svg class="map-art" viewBox="0 0 500 900" preserveAspectRatio="xMidYMid slice" aria-label="Illustrative Bohol route map"><defs><pattern id="blocks" width="55" height="58" patternUnits="userSpaceOnUse"><path d="M0 8H55M12 0V58" stroke="#f7f6eb" stroke-width="4"/><rect x="19" y="17" width="22" height="26" rx="5" fill="#d5ddcc"/></pattern></defs><rect width="500" height="900" fill="#c8e0eb"/><path d="M0 0H500V780l-65-52-55-65-110-20-45-50-74-60-36-83-56-35L0 375Z" fill="#e7eddf"/><path d="M0 0H500V780l-65-52-55-65-110-20-45-50-74-60-36-83-56-35L0 375Z" fill="url(#blocks)" opacity=".65"/><path d="M330 0 310 170 350 260 290 320 315 420 240 490 270 570 215 625" stroke="#bad1b3" stroke-width="65" fill="none" opacity=".7"/><path d="M0 170 170 240 250 350 350 360 500 420M100 0 120 200 200 340 195 450 260 570 420 650M0 380 160 450 230 535 330 560 500 600M250 0 260 180 380 260 500 270" stroke="#fff" stroke-width="12" fill="none"/><path d="M0 170 170 240 250 350 350 360 500 420M100 0 120 200 200 340 195 450 260 570 420 650M0 380 160 450 230 535 330 560 500 600" stroke="#e5c68c" stroke-width="5" fill="none"/><path d="M60 670q85-50 160 5l32 70-50 55-110-20-48-58Z" fill="#e7eddf"/><path d="M230 535 182 610 150 688 98 725" stroke="white" stroke-width="10" fill="none"/><g fill="#788b7f" font-size="12" font-family="Arial"><text x="310" y="220">Sikatuna Tree Park</text><text x="78" y="302">Cortes</text><text x="270" y="318">Corella</text><text x="328" y="407">Sikatuna</text><text x="130" y="500">Tagbilaran City</text><text x="280" y="585">Baclayon</text><text x="120" y="640">Dauis</text><text x="70" y="760">Panglao</text><text x="28" y="585" fill="#739aad">Bohol Strait</text></g>${showRoute?`<path d="M350 360 250 350 195 450 230 535 182 610 150 688 98 725" stroke="white" stroke-width="10" fill="none"/><path d="M350 360 250 350 195 450 230 535 182 610 150 688 98 725" stroke="#3d89db" stroke-width="5" fill="none" stroke-linejoin="round"/><g stroke="white" stroke-width="3"><circle cx="350" cy="360" r="12" fill="#061b41"/><circle cx="230" cy="535" r="12" fill="#ff7900"/><circle cx="98" cy="725" r="12" fill="#ff7900"/></g><g fill="white" text-anchor="middle" font-family="Arial" font-size="11"><text x="350" y="364">P</text><text x="230" y="539">1</text><text x="98" y="729">2</text></g><circle cx="302" cy="355" r="9" fill="#1682fa" stroke="white" stroke-width="4"/>`:''}</svg>`}
function tripMapTitle(b,driverView){
  const titles=driverView?{'Pending':'Pending','Accepted':'Accepted · Map preview','On the way':'Driver on the way','Arrived':'Driver has arrived','In Progress':'In Progress','Completed':'Service completed'}:{'Pending':'Your booking','Accepted':'Accepted','On the way':'Driver on the way','Arrived':'Your driver is here','In Progress':'On your trip','Completed':'Trip complete'};
  return (driverView?'<small>DRIVER WORKSPACE</small>':'')+esc(titles[b.status]||'Booking '+b.status.toLowerCase());
}
function tripSheetBody(b,driverView){
  const d=people[b.driver],active=b.status==='In Progress',closed=['Completed','Cancelled','Declined'].includes(b.status);
  const heading={'Pending':'Your booking is pending.','Accepted':'Your booking has been accepted.','On the way':'Your driver is heading to your pickup.','Arrived':'Meet at your pickup.','In Progress':'Enjoy your journey.','Completed':'Thanks for riding.','Cancelled':'Booking cancelled','Declined':'Request not accepted.'};
  const peer=`<div class="trip-peer">${img(driverView?'mika':d.photo)}<div class="trip-peer-info"><b>${esc(driverView?state.profile.name:d.name)}</b>${driverView?'<small>Your customer</small>':`<small class="trip-rating">★ ${d.rating}</small><small>${esc(b.vehicle)}</small>`}</div>${!closed?`<button class="trip-message" aria-label="${driverView?'Message Customer':'Message Driver'}" ${action('go','chat')}>${icon('message')}<span>Message</span></button>`:''}</div>`;
  const requests=`${b.extension?`<div class="card trip-extension"><b>Extension ${b.extension.status.toLowerCase()}</b><p class="helper">+${b.extension.minutes} minutes · ${money(d.rate*b.extension.minutes/60)}</p>${driverView&&b.extension.status==='Pending'?`<div class="actions">${btn('Decline','extension-decline','','outline small')}${btn('Accept Extension','extension-accept','','small')}</div>`:''}</div>`:''}${b.extra?`<div class="card"><h4>Destination request</h4><p>${esc(b.extra)}</p>${driverView?`<div class="actions">${btn('Decline','extra-decline','','outline small')}${btn('Accept','extra-accept','','small')}</div>`:'<small class="muted">Waiting for driver approval</small>'}</div>`:''}`;
  if(driverView){
    const target=active?b.destinations[b.visited||0]||'All destinations visited':b.pickup;
    return `<p class="trip-eyebrow">${active?'NEXT DESTINATION':'PICKUP LOCATION'}</p><h2 class="trip-heading">${esc(target)}</h2><p class="trip-caption">${active?'Customer-selected destination':'Customer-pinned location'}</p>${peer}${b.notes?`<p class="trip-time">${esc(b.notes)}</p>`:''}${requests}<div class="trip-schedule"><span>${demoDate(b.date)} · ${demoTime(b.time)}</span><span>Booked for ${b.hours} hours</span></div>${driverTripActions(b)}${active||closed?btn('View trip details','go','trip-details','small'):''}${b.status==='Completed'?btn('Return to bookings','booking-tab','Completed','outline small'):''}`;
  }
  const end=new Date(b.date+'T'+b.time);end.setMinutes(end.getMinutes()+b.hours*60+(b.extension?.status==='Approved'?b.extension.minutes:0));
  const timer=active?`Service Time<br>${b.hours}h remaining<br>Ends at ${end.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}<br>${b.extension?.status==='Pending'?'Extension request pending':'Request more time →'}`:closed?'Service ended':'Timer starts after pickup';
  return `<p class="trip-state">${esc(b.status)}</p><h2 class="trip-heading">${heading[b.status]||esc(b.status)}</h2>${peer}<div class="trip-divider"></div>${route(b)}<button class="trip-time" ${active&&b.extension?.status!=='Pending'?action('open-extension'): 'disabled'}>${timer}</button>${requests}${active?`<div class="trip-actions">${btn('Add a destination','new-destination')}${btn('Emergency help','go','sos','outline trip-emergency')}</div>`:''}`;
}
function tripMap(isPicker=false,isHistory=false){const b=currentBooking(),d=people[b.driver],driverView=state.role==='driver';let body='';if(isPicker){body=`<h3>${pickerTarget==='pickup'?'Pickup location':'Destination location'}</h3><p class="muted small-text">Move the map to position the pin.</p>${field('Place or landmark','pin-name',pickerName,'text','Name this location')}${btn('Confirm Location','confirm-pin')}`}
else if(isHistory){body=`<h3>Route details</h3>${route(b)}${kv('Completed booking',b.id)}`}
else{body=tripSheetBody(b,driverView)}
return `<div class="map-screen ${isPicker?'picker':''} ${fullMap?'full':''} ${state.mapType==='Satellite'?'satellite':''}"><div class="map-canvas" id="map-canvas">${mapArt(!isPicker)}</div>${isPicker?'<div class="centerpin">'+icon('pin')+'</div>':''}<div class="map-header">${ib('back','back','','Back')}<div class="map-title">${isPicker?'Choose location':isHistory?'Trip map':tripMapTitle(b,driverView)}</div>${ib('expand','map-full','','Toggle full screen')}</div><div class="map-controls">${ib('layers','map-type','','Select map type')}${ib('locate','locate','','Current location')}</div><span class="map-caption">Illustrative map · Bohol demo</span><div class="map-panel ${mapCollapsed?'collapsed':''}"><button class="handle" aria-label="Expand or collapse route details" ${action('map-collapse')}></button>${body}</div>${fullMap?`<button class="btn outline small" style="position:absolute;bottom:23px;left:73px;z-index:7;width:auto" ${action('map-full')}>Route details</button>`:''}</div>`}
function driverTripActions(b){let controls='';if(b.status==='Accepted')controls=btn('Start Going to Pickup','trip-step','On the way');else if(b.status==='On the way')controls=btn("I've arrived",'trip-step','Arrived');else if(b.status==='Arrived')controls=btn('Start Service','trip-step','In Progress');else if(b.status==='In Progress')controls=btn('Reached this destination','reach','','outline')+`<p class="helper">Destination ${b.visited+1} of ${b.destinations.length} · Service completes at the last destination.</p>`;return `<div style="margin:18px 0">${controls}</div>`}
function customerTripActions(b){return b.status==='In Progress'?`<div style="margin:20px 0">${btn('Extend service time →','open-extension','','outline small')}<div style="height:9px"></div>${btn('Add destination →','new-destination','','outline small')}<button class="text-btn" style="color:#b7473f" ${action('go','sos')}>Emergency assistance</button></div>`:''}
function extensionSheet(){const b=currentBooking();selectedExtra=30;modal('Extend service time',`<p>Choose how much more time you need.</p><div class="card pale"><h4>CURRENT BOOKING</h4>${kv('Booked time',b.hours+'h')}${kv('Hourly rate',money(people[b.driver].rate)+'/hr')}</div><h4>Additional time</h4><div id="extension-choices">${[30,60,120].map(n=>`<button class="choice ${n===selectedExtra?'active':''}" ${action('extension-minutes',n)}>${n<60?n+' minutes':n/60+' hour'+(n>60?'s':'')} · ${money(people[b.driver].rate*n/60)}</button>`).join('')}<label class="field"><span>Custom duration (minutes)</span><input id="custom-minutes" type="number" min="15" max="480" step="15" placeholder="Optional"></label></div><div class="card" style="background:#fff8ef">${kv('Additional fee',`<b id="extra-fee">${money(people[b.driver].rate/2)}</b>`)}${kv('Total duration',`<b id="extra-total">${b.hours+.5} hours</b>`)}</div><p class="small-text">Your driver must approve the request before extra time and fees are added.</p>`,btn('Cancel','close','','outline')+btn('Send request','send-extension'),true)}
function profile(){const drv=state.role==='driver';return page(drv?'Profile':'My Profile',`<div class="profile-top">${img(drv?people[0].photo:'mika','avatar big')}<h2>${esc(drv?people[0].name:state.profile.name)}</h2><p>${esc(drv?'mark.demo@example.com':state.profile.email)}</p></div>${drv?`<div class="stats"><div><b>4.9</b><small>Rating</small></div><div><b>${state.bookings.filter(b=>b.status==='Completed').length}</b><small>Completed</small></div><div><b>6</b><small>Years Exp.</small></div></div><h4 style="margin-top:20px">Account Settings</h4>${menu('Personal Information','user','edit')}${menu('Driving Information','car','driving')}${menu('Change Password','settings','password')}${menu('Documents','file','documents')}${menu('Customer Reviews','star','reviews','View customer ratings and feedback')}${menu('Availability & Schedule','calendar','schedule')}<h4 style="margin-top:22px">Support</h4>${menu('Help Center','help','help')}${menu('Contact Support','message','support')}${menu('Settings','settings','settings')}`:`${menu('Edit Profile','user','edit','Update your personal information')}${menu('My Reviews','star','reviews','View your ratings and feedback')}${menu('Emergency Contact','phone','emergency','Manage your emergency contact')}${menu('Settings','settings','settings','Preferences and account settings')}`}<div style="margin-top:25px">${btn('Logout','logout','','outline')}</div>`,{nav:'profile'})}
function menu(title,i,target,sub=''){return `<button class="listrow" ${action('go',target)}>${icon(i)}<span class="grow">${title}${sub?'<small>'+sub+'</small>':''}</span><span class="chev">›</span></button>`}
function editProfile(setup=false){const drv=state.role==='driver';return page(setup?'Set Up Your Profile':drv?'Personal Information':'Edit Profile',`<div style="text-align:center;margin-bottom:24px">${img(drv?people[0].photo:'mika','avatar big')}<br><button class="text-btn" ${action('upload','profile')}>Change Profile Picture</button></div>${field('Full Name','profile-name',drv?people[0].name:state.profile.name)}${field('Email Address','profile-email',drv?'mark.demo@example.com':state.profile.email,'email')}${field('Phone Number','profile-phone',state.profile.phone,'tel')}${field('Address','profile-address',state.profile.address,'text','Barangay, Municipality, Province')}`,{bottom:btn(setup?'Continue':'Save Changes','save-profile',setup?'setup':'')})}
function settings(){return page(state.role==='driver'?'Driver Settings':'Settings',`<h4 class="muted">APP PREFERENCES</h4>${menu('Notifications','bell','notification-settings','Manage alerts and updates')}${state.role==='customer'?menu('Language','message','language',state.language||'English'):''}${menu('Location Permissions','pin','location-settings','Manage location access for maps and trips')}<h4 class="muted" style="margin-top:26px">ACCOUNT</h4>${menu('Change Password','settings','password')}${state.role==='customer'?menu('Delete Account','user','delete'):''}<h4 class="muted" style="margin-top:26px">PRIVACY & INFORMATION</h4>${menu('Terms & Conditions','file','terms')}${menu('Privacy Policy','shield','privacy')}${menu('Help & Support','help','help')}${menu('About HireMyDriver','car','about')}`)}
function driving(){return page('Driving Information',`<h3>Vehicle Types I Can Drive</h3><p class="helper">Select all that apply.</p>${chips(vehicles,state.drivingTypes||people[0].types,'driving-vehicle')}<h3>Transmission I Can Drive</h3>${chips(['Automatic','Manual'],state.transmission||['Automatic','Manual'],'transmission')}${field('Years of Driving Experience','driving-years',6,'number')}${pick('Preferred Service Area',(state.areas||['Sikatuna','Tagbilaran']).join(', '),'areas','driving')}<h3>Languages Spoken</h3>${chips(['Filipino','English','Cebuano/Bisaya'],state.languages||['English','Cebuano/Bisaya'],'driving-language')}${field('Hourly Rate (₱ / hour)','driving-rate',people[0].rate,'number')}<p class="helper">Customers will see this hourly rate on your profile.</p>`,{bottom:btn('Save Changes','save-driving')})}
function schedule(){return page('Availability & Schedule',`<div class="row between"><div><h3>Availability</h3><p class="small-text muted">Receive new booking requests</p></div><button class="toggle ${state.available?'on':''}" aria-label="Toggle availability" ${action('availability')}></button></div><h3 style="margin-top:26px">Weekly Schedule</h3><p class="helper">Select your available days and working hours.<br>All times are in Philippine time.</p>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(day=>{const s=state.schedule.find(s=>s.day===day);return `<div class="schedule"><input aria-label="Available ${day}" type="checkbox" data-day="${day}" style="width:17px;accent-color:#ff7900" ${s?.enabled?'checked':''}><b>${day.slice(0,3)}</b><input aria-label="${day} start time" type="time" data-start="${day}" value="${s?.start||'06:00'}"><span>–</span><input aria-label="${day} end time" type="time" data-end="${day}" value="${s?.end||'18:00'}"></div>`}).join('')}`,{bottom:btn('Save Schedule','save-schedule')})}
function reviewCards(){return state.reviews.filter(r=>state.reviewFilter==='See All'||r.rating===parseInt(state.reviewFilter)).map(r=>`<div class="card"><div class="row">${img(r.photo)}<div><b>${esc(r.name)}</b><div class="rating" style="margin-top:6px">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div></div></div><p class="small-text muted" style="margin:15px 0 0">${esc(r.text)}</p></div>`).join('')||'<p class="empty">No reviews for this rating yet.</p>'}
function reviews(){return page(state.role==='driver'?'Customer Reviews':'Driver Reviews',`<div class="review-filters">${chips(['See All','5 Stars','4 Stars','3 Stars','2 Stars','1 Star'],state.reviewFilter,'review-filter')}</div>${reviewCards()}`)}
function rate(){const b=currentBooking();return page('Rate Driver',`${userRow(b)}<h3 style="text-align:center;margin-top:35px">Your Rating</h3><div class="review-stars">${[1,2,3,4,5].map(n=>`<button aria-label="${n} stars" class="${state.rating>=n?'active':''}" ${action('rating',n)}>★</button>`).join('')}</div><p style="text-align:center" class="muted">${state.rating}.0 – ${['','Poor','Fair','Good','Very Good','Excellent'][state.rating]}</p><label class="field"><span>Write a Review</span><textarea id="review-text" maxlength="500" placeholder="Share your experience with this driver…">${esc(state.reviewDraft||'')}</textarea></label><h4>What did you like? <small class="muted">(Optional)</small></h4>${chips(['Punctual','Professional','Safe Driving','Good Communication','Friendly'],state.reviewTags||[],'review-tag')}`,{bottom:btn('Submit Review','submit-review')})}
function success(title,description,button,next,secondary='',next2=''){return `<div class="scroll success"><div class="success-check">${icon('check')}</div><h2>${title}</h2><p>${description}</p>${btn(button,'go',next)}${secondary?btn(secondary,'go',next2,'outline'):''}</div>`}
function notifications(){return page('Notifications',`${state.notifications[state.role].length?state.notifications[state.role].map((n,i)=>`<button class="notification" style="${n.read?'':'background:#fffbf7'}" ${action('notification',i)}><span class="iconbox">${icon('bell')}</span><span class="grow"><b>${esc(n.title)}</b><p>${esc(n.text)}</p><small>${n.read?'Read':'New'} · Demo update</small></span></button>`).join(''):'<p class="empty">No notifications yet.</p>'}`)}
function messages(){return page('Messages',`<div class="tabs" style="padding:0 0 18px"><button class="active" ${action('message-tab','All')}>All</button><button ${action('message-tab','Unread')}>Unread</button></div><div id="message-list"><button class="listrow" ${action('go','chat')}>${img(state.role==='driver'?'mika':people[currentBooking().driver].photo)}<span class="grow"><b>${state.role==='driver'?esc(state.profile.name):esc(people[currentBooking().driver].name)}</b><small>${esc(state.messages.at(-1)?.text||'Start a conversation')}</small></span><small>9:41</small></button></div>`,{nav:'messages'})}
function chat(){const b=currentBooking();return header(state.role==='driver'?esc(state.profile.name.split(' ')[0]):esc(people[b.driver].name.split(' ')[0]))+`<div style="padding:12px 20px;background:#f7f8fb;color:#8190a0;font-size:11px">Booking ${b.id} · ${b.status}</div><div class="scroll pad" id="conversation"><p class="helper" style="text-align:center">Today · Demo conversation</p>${state.messages.map(m=>`<div class="bubble ${m.role===state.role?'mine':''}">${esc(m.text)}</div>`).join('')}</div><form id="chat-form" class="composer"><input id="chat-text" aria-label="Message" placeholder="Type a message…" autocomplete="off"><button aria-label="Send message" type="submit">${icon('arrow')}</button></form>`}
function login(){const drv=state.role==='driver';return `<div class="scroll">${ib('back','go','welcome','Back')}<div class="auth"><h2>${drv?'Driver Login':'Welcome Back!'}</h2><p class="subtitle small-text">${drv?'Sign in to start receiving driving jobs':'Login to your account'}</p>${field('Email','login-email',drv?'mark.demo@example.com':'sofia.demo@example.com','email')}${field('Password','login-password','Demo123!','password')}<div style="text-align:right"><button class="text-btn" ${action('go','forgot')}>Forgot Password?</button></div>${btn('Login','login','','navy')}<p class="auth-footer">Don't have an account? <button class="text-btn" ${action('go',drv?'registration':'signup')}>Sign Up</button></p>${!drv?'<div class="divider">or continue with</div>'+btn(img('logo_google','google','Google')+' Continue with Google','google','','outline'):''}<p class="helper" style="text-align:center">Demo account is filled in for your presentation.</p></div></div>`}
function signup(driverRegistration=false){return page(driverRegistration?'Driver Registration':'Create Account',`${driverRegistration?steps(0):'<p class="muted small-text">Fill in your details to create your customer account</p>'}${field('Full Name','signup-name',driverRegistration?'Mark Laurence Polinar':'Sofia Reyes')}${field('Email Address','signup-email',driverRegistration?'mark.demo@example.com':'sofia.demo@example.com','email')}${field('Phone Number','signup-phone','0917 000 0123','tel')}${field('Password','signup-password','Demo123!','password')}${field('Confirm Password','signup-confirm','Demo123!','password')}<label class="row small-text"><input id="agree" type="checkbox" checked style="accent-color:#ff7900"> I agree to the <button class="text-btn" ${action('go','terms')}>Terms & Conditions</button></label>`,{bottom:btn(driverRegistration?'Next':'Sign Up','signup',driverRegistration?'driver':'customer')})}
function steps(n){return `<div class="steps">${['Account','Personal Info','Requirements','Review'].map((s,i)=>`<div class="${i<=n?'active':''}"><b>${i<n?'✓':i+1}</b>${s}</div>`).join('')}</div>`}
function uploadButton(name,label){return `<button class="upload" ${action('upload',name)}>${icon(state.uploads[name]?'check':'upload')}<span>${state.uploads[name]?'Demo '+label+' added':label}</span></button>`}
function documents(reg=false){return page(reg?'Driver Requirements':'Documents',`${reg?steps(2):'<span class="badge green">'+icon('shield')+' Verified Driver</span>'}<h3 style="margin-top:25px">Driver's License</h3>${field('License Number','license-number','DEMO-LICENSE-001')}${field('License Expiration Date','license-expiry','2028-10-22','date')}<div class="fields-row">${uploadButton('license-front','License front')}${uploadButton('license-back','License back')}</div><h3 style="margin-top:25px">Police Clearance</h3>${field('Date of Issue','clearance-issue','2026-10-01','date')}${field('Validity Date','clearance-expiry','2027-04-01','date')}${uploadButton('clearance','Police clearance')}<p class="helper">Presentation documents only. No personal documents are uploaded.</p>`,{bottom:btn(reg?'Next':'Save Changes',reg?'registration-review':'save-documents')})}
function registrationPersonal(){return page('Personal Information',`${steps(1)}${field('Date of Birth','birthday','1995-06-15','date')}${field('Address','registration-address','Poblacion, Sikatuna, Bohol')}${uploadButton('selfie','Live selfie')}${field('Years of Driving Experience','experience','6','number')}<label class="field"><span>Short Description / Bio</span><textarea id="bio">Safe, professional driving services around Bohol.</textarea></label>`,{bottom:btn('Next','go','registration-documents')})}
function registrationReview(){return page('Review Information',`${steps(3)}<h3>Review your information</h3><p class="helper">Check your details before submitting for verification.</p><div class="card"><h4>Account Information</h4>${kv('Full Name',esc(state.registrationName||people[0].name))}${kv('Email Address',esc(state.registrationEmail||'mark.demo@example.com'))}</div><div class="card"><h4>Personal Information</h4>${kv('Address','Poblacion, Sikatuna, Bohol')}${kv('Driving Experience','6 years')}${kv('Profile Picture','Demo selfie')}</div><div class="card"><h4>Requirements</h4>${kv("Driver's License",'Front & back')}${kv('Police Clearance','Demo document')}</div>`,{bottom:btn('Submit for Verification','submit-verification')})}
function emergency(){return page('Emergency Contact',`<p class="muted small-text">Someone we can contact if you need assistance.</p>${field('Full Name','emergency-name',state.emergency?.name||'Alex Reyes')}${field('Phone Number','emergency-phone',state.emergency?.phone||'0917 000 0456','tel')}${pick('Relationship',state.emergency?.relationship||'Family','relationship')}`,{bottom:btn('Save Contact','save-emergency')})}
function help(){return page('Help Center',`<h3>How can we help you?</h3><p class="muted small-text">Find answers to common questions.</p>${[['How do I book a driver?','Choose a driver, select an available date and time, pin your pickup and destinations, and send your booking request.'],['Can I cancel my request?','Open Pending Bookings and tap Cancel Booking. Select a reason and continue.'],['How do extensions work?','During service, request more time from the trip map. Your driver reviews the additional time and fee.'],['When is a trip completed?','The driver confirms arrival at each stop. Confirming the final destination completes the booking.'],['How are drivers verified?','Drivers provide personal information, a live selfie, their license, and police clearance for review.'],['How do I pay?','The booking summary shows the hourly fee and Cash payment method.']].map(([q,a])=>`<details style="border-bottom:1px solid #eee;padding:17px 0"><summary style="cursor:pointer;font-weight:600;font-size:14px">${q}</summary><p class="small-text muted" style="margin:15px 0 0">${a}</p></details>`).join('')}<div style="margin-top:25px">${btn('Contact Support','go','support','outline')}</div>`)}
function renderScreen(){switch(state.screen){
case 'onboarding':return `<div class="onboarding">${img('onboard_'+(state.onboard+1),'onboarding-art','Onboarding '+(state.onboard+1))}<div class="onboarding-controls"><div class="dots">${[0,1,2,3].map(i=>`<button aria-label="Onboarding page ${i+1}" class="${i===state.onboard?'active':''}" ${action('onboard-page',i)}></button>`).join('')}</div><div class="onboarding-footer"><button class="text-btn" ${action('go','welcome')}>Skip</button>${btn(state.onboard===3?'Get Started':'Next','onboard-next')}</div></div></div>`;
case 'welcome':return `<div class="welcome" style="background-image:url('${art('img_car_bg')}')">${img('logo_app','logo','HireMyDriver')}<h2>Hire<span class="orange">MyDriver</span></h2><small>Your Trusted Driver Anytime.</small><div class="welcome-actions">${btn("I'm a Customer",'role-login','customer')}${btn("I'm a Driver",'role-login','driver','outline')}</div></div>`;
case 'login':return login();case 'signup':return signup();case 'registration':return signup(true);case 'registration-personal':return registrationPersonal();case 'registration-documents':return documents(true);case 'registration-review':return registrationReview();
case 'verification':return success('Submitted for verification','Your driver information has been submitted for review. In the live app, verification is completed by an administrator.','Back to Login','login');
case 'setup':return editProfile(true);case 'forgot':return `<div class="scroll">${ib('back','back','','Back')}<div class="auth"><h2>Forgot Password?</h2><p class="muted small-text">Enter your email address and we will send you a link to reset your password.</p>${field('Email Address','reset-email',state.role==='driver'?'mark.demo@example.com':'sofia.demo@example.com','email')}${btn('Send reset link','reset-password','','navy')}</div></div>`;
case 'home':return home();case 'recommended':case 'popular':case 'results':return listDrivers();case 'filter':return filters();case 'best':return best();case 'driver':return driverProfile();case 'book':return book();case 'confirm':return reviewBooking();case 'booked':return success('Booking Request Sent!','Your request has been sent to the driver. You will be notified once it is accepted.','View My Bookings','bookings','Back to Home','home');case 'bookings':return bookings();case 'details':return bookingDetails();case 'trip-details':return bookingDetails(true);case 'trip':case 'extension':case 'destination':return tripMap();case 'picker':return tripMap(true);case 'history':return tripMap(false,true);case 'rate':return rate();case 'reviewed':return success('Review Submitted!','Thank you for sharing your experience. Your feedback helps other customers find the right driver.','View My Review','reviews','Back to Home','home');case 'reviews':return reviews();case 'profile':return profile();case 'edit':return editProfile();case 'settings':return settings();case 'driving':return driving();case 'schedule':return schedule();case 'documents':return documents();case 'notifications':return notifications();case 'messages':return messages();case 'chat':return chat();case 'emergency':return emergency();case 'help':return help();
case 'notification-settings':case 'location-settings':{const loc=state.screen==='location-settings';return page(loc?'Location Permissions':'Notifications',`<div class="row between"><div><h3>${loc?'Location access':'Booking notifications'}</h3><p class="muted small-text">${loc?'For maps, nearby drivers, and tracking.':'Requests, trip progress, and service updates.'}</p></div><button class="toggle ${state.settings[loc?'location':'notifications']?'on':''}" aria-label="Toggle ${loc?'location':'notifications'}" ${action('setting',loc?'location':'notifications')}></button></div>${loc?btn('Review Location Permission','permission','','outline'):''}<p class="helper">This changes the demo preference only. The installed app uses your phone’s permission settings.</p>`)}
case 'language':return page('Language',chips(['English','Filipino','Cebuano/Bisaya'],state.language||'English','language')+'<p class="helper">Language preference preview. Presentation text remains in English.</p>');
case 'password':return page('Change Password',field('Current Password','old-password','','password')+field('New Password','new-password','','password')+field('Confirm New Password','confirm-password','','password'),{bottom:btn('Save Changes','change-password')});
case 'support':return page('Contact Support',`<h3>How can we help?</h3><p class="muted small-text">Tell us about your booking or account concern.</p>${field('Email Address','support-email',state.profile.email,'email')}${field('Subject','support-subject','Booking assistance')}<label class="field"><span>Message</span><textarea id="support-message" placeholder="Describe your concern…"></textarea></label>`,{bottom:btn('Send Message','send-support')});
case 'about':return page('About HireMyDriver',`<div class="profile-top">${img('logo_app','avatar big','HireMyDriver logo')}<h2>Hire<span class="orange">MyDriver</span></h2><p>Your Trusted Driver Anytime.</p></div><p class="legal">HireMyDriver helps customers find verified drivers based on their location, schedule, and travel needs. Manage bookings, communicate with your driver, track trips, and share your experience.</p><div class="card">${kv('Customer','Discover and book drivers')}${kv('Driver','Manage requests and trips')}</div><p class="helper">Interactive presentation based on the Android app. All people, bookings, fees, reviews, and actions in this demo are illustrative.</p>`);
case 'terms':case 'privacy':return page(state.screen==='terms'?'Terms & Conditions':'Privacy Policy',`<div class="legal"><h3>${state.screen==='terms'?'Using HireMyDriver':'Your information'}</h3><p>${state.screen==='terms'?'Provide accurate account and booking information. Review the driver’s availability, service area, and hourly rate before sending a request. Treat your driver and customer with respect.':'Account details, driver requirements, location information, bookings, messages, and reviews support the app experience. Location access is controlled through device permissions.'}</p><h3>${state.screen==='terms'?'Bookings and service':'Your choices'}</h3><p>${state.screen==='terms'?'Requests are subject to driver acceptance. Any additional time or destination must be approved by the driver. Review the final booking summary and agreed payment method.':'You can manage profile details, notification preferences, and location access in settings. Contact support for account concerns.'}</p><p class="helper">Presentation summary. Refer to the installed app for the complete policy wording. This local demo does not contact Firebase or collect account credentials.</p></div>`);
case 'sos':return page('Emergency Assistance',`<div class="profile-top">${icon('shield')}<h2>Need help?</h2><p>Review your emergency contact.</p></div><div class="card"><h3>${esc(state.emergency?.name||'Alex Reyes')}</h3><p class="muted">${esc(state.emergency?.phone||'0917 000 0456')}</p></div><p class="helper">Presentation only. No call or emergency alert will be sent.</p>`,{bottom:btn('Preview Emergency Alert','emergency-preview','','danger')});
case 'delete':return page('Delete Account',`<h3>Delete your account?</h3><p class="muted small-text">Review this action before proceeding. This presentation can only reset the sample account.</p>${field('Type DELETE to confirm','delete-text')}`,{bottom:btn('Delete Demo Account','delete-account','','danger')});
case 'offline':return page('Home','<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>',{nav:'home'});
default:return page('HireMyDriver','<p>Select a screen from the presentation menu.</p>');}}
function render(){const s=state.screen;$('#app').innerHTML=renderScreen();$('#statusbar').classList.toggle('dark',!['login','forgot','onboarding','booked','reviewed','verification','welcome','trip','picker','history','extension','destination'].includes(s)||s==='welcome');const meta=screens.find(x=>x[0]===s);$('#screen-caption').textContent=meta?.[3]||({results:'Driver matches','registration-personal':'Personal information','registration-documents':'Driver requirements','registration-review':'Review information','trip-details':'Trip details',verification:'Verification pending'}[s]||'HireMyDriver');$('#screen-note').textContent=meta?.[4]||'Explore the app by tapping the phone.';$('#role-caption').textContent=state.role==='driver'?'Driver experience':'Customer experience';$('#customer-mode').classList.toggle('active',state.role==='customer');$('#driver-mode').classList.toggle('active',state.role==='driver');directory();bindMap();if(s==='chat'&&$('#conversation'))$('#conversation').scrollTop=$('#conversation').scrollHeight;resizePhone();}
function directory(){const search=$('#screen-search').value.toLowerCase();let group='';const available=screens.filter(x=>x[1]==='shared'||x[1]===state.role);$('#compact-role').value=state.role;$('#compact-screen').innerHTML=available.map(x=>`<option value="${x[0]}" ${x[0]===state.screen?'selected':''}>${x[3]}</option>`).join('');$('#screen-directory').innerHTML=available.filter(x=>!search||x.slice(2).join(' ').toLowerCase().includes(search)).map((x,i)=>{const heading=group!==x[2]?`<h3>${x[2]}</h3>`:'';group=x[2];return heading+`<button ${action('jump',x[0])} class="${state.screen===x[0]?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${x[3]}</button>`}).join('')}
function resizePhone(){const box=$('.phone-wrap');document.documentElement.style.setProperty('--phone-scale',Math.min((box.clientHeight-20)/844,(box.clientWidth-22)/400,1));}
function bindMap(){const canvas=$('#map-canvas');if(!canvas)return;let down=null;const apply=()=>{$('.map-art').style.transform=`translate(${pin.x}px,${pin.y}px)`};apply();canvas.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,px:pin.x,py:pin.y};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging')});canvas.addEventListener('pointermove',e=>{if(!down)return;const scale=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--phone-scale'));pin.x=Math.max(-100,Math.min(100,down.px+(e.clientX-down.x)/scale));pin.y=Math.max(-160,Math.min(160,down.py+(e.clientY-down.y)/scale));apply()});const end=()=>{down=null;canvas.classList.remove('dragging')};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);}
function toggleArray(key,value,fallback=[]){const a=state[key]||[...fallback];state[key]=a.includes(value)?a.filter(x=>x!==value):[...a,value]}
function areas(kind){selectedAreas=kind==='driving'?[...(state.areas||['Sikatuna','Tagbilaran'])]:[kind==='best'?(state.bestArea||'Sikatuna'):state.filter.area];state.areaKind=kind;modal(kind==='driving'?'Preferred Service Area':'Select Service Area',`<input id="area-search" class="searchbox" aria-label="Search areas" placeholder="Search city, municipality or province"><p class="small-text" style="margin-top:18px">Suggested areas in Bohol. ${kind==='driving'?'Select the areas you serve.':'Select the area where you need a driver.'}</p><div id="area-choices" style="max-height:290px;overflow:auto">${areaChoices('')}</div>`,btn('Cancel','close','','outline')+btn('Apply','apply-area'))}
function areaChoices(query){return BOHOL.filter(a=>a.toLowerCase().includes(query.toLowerCase())).map(a=>`<button class="choice ${selectedAreas.includes(a)?'active':''}" ${action('choose-area',a)}>${esc(a)} (Bohol)</button>`).join('')}
function ensureDemoTrip(){let b=currentBooking();if(['Completed','Cancelled','Declined'].includes(b.status)){b=state.bookings.find(x=>x.status==='In Progress')||state.bookings.find(x=>!['Completed','Cancelled','Declined'].includes(x.status));if(b)state.selected=b.id;}b=currentBooking();b.status='In Progress';return b}
function jump(screen){if(['extension','destination'].includes(screen)){const b=ensureDemoTrip();if(state.role==='driver'){if(screen==='extension')b.extension={minutes:30,status:'Pending'};else b.extra='Baclayon Church';}go(screen);if(state.role==='customer'){if(screen==='extension')extensionSheet();else newDestination();}return}if(screen==='trip')ensureDemoTrip();if(['rate','history','reviewed'].includes(screen)){state.selected=state.bookings.find(b=>b.status==='Completed')?.id||state.selected;}if(screen==='book'||screen==='confirm'||screen==='booked'){state.form={...state.form,pickup:'Sikatuna Municipal Hall',destinations:['Island City Mall, Tagbilaran','Panglao International Airport']};}if(screen==='picker'){pickerTarget='pickup';pickerReturn='book';pickerName=state.form.pickup||'Sikatuna Municipal Hall';}if(screen==='bookings')state.tab=state.role==='driver'?'Requests':'All';go(screen);if(screen==='offline'){offline=true;offlineDialog();}}
function offlineDialog(){modal('No internet connection','<p>Please connect to the internet and try again.</p>',btn('Cancel','offline-cancel','','outline')+btn('Try again','offline-retry'));}
function newDestination(){const b=currentBooking();if(b.extra){toast('A destination request is already waiting for driver approval.');return}pickerTarget='extra';pickerReturn='trip';pickerName='';pin={x:0,y:0};go('picker')}
function perform(a,v,el){const b=currentBooking();switch(a){
case 'go':go(v);break;case 'back':back();break;case 'close':closeModal();break;
case 'jump':jump(v);break;case 'role':setRole(v);break;case 'role-login':state.role=v;go('login');break;
case 'focus':document.body.classList.toggle('focus');resizePhone();break;
case 'reset':state=fresh();history=[];pin={x:0,y:0};fullMap=false;offline=false;$('#screen-search').value='';go('onboarding',false);break;
case 'tour-next':case 'tour-prev':{const list=screens.filter(x=>x[1]==='shared'||x[1]===state.role);let i=list.findIndex(x=>x[0]===state.screen);i=(i+(a==='tour-next'?1:-1)+list.length)%list.length;jump(list[i][0]);break}
case 'onboard-next':if(state.onboard<3){state.onboard++;render()}else go('welcome');break;
case 'onboard-page':state.onboard=Number(v);render();break;
case 'login':if(!$('#login-email').validity.valid||!$('#login-email').value||!$('#login-password').value){toast('Enter an email address and password.');break}go('home');break;
case 'google':modal('Continue with Google',`<p>Choose the sample account for this presentation.</p><button class="choice" ${action('google-login')}>${img('mika','avatar')}<span>Sofia Reyes<br><small>sofia.demo@example.com</small></span></button><p class="helper">Google authentication is simulated in this local demo.</p>`);break;
case 'google-login':go('home');break;
case 'signup':if(!$('#agree').checked){toast('Please agree to the Terms & Conditions.');break}if(!$('#signup-name').value.trim()||!$('#signup-email').validity.valid||!$('#signup-email').value){toast('Enter your name and a valid email address.');break}if($('#signup-password').value.length<6||$('#signup-password').value!==$('#signup-confirm').value){toast('Use at least 6 characters and matching passwords.');break}if(v==='driver'){state.registrationName=$('#signup-name').value;state.registrationEmail=$('#signup-email').value;go('registration-personal')}else{state.profile.name=$('#signup-name').value;state.profile.email=$('#signup-email').value;state.profile.phone=$('#signup-phone').value;go('setup')}break;
case 'registration-review':go('registration-review');break;case 'submit-verification':go('verification');break;
case 'upload':state.uploads[v]=true;render();toast('Sample '+v.replaceAll('-',' ')+' added for the presentation.');break;
case 'save-documents':toast('Demo documents saved.');break;
case 'reset-password':if(!$('#reset-email').value||!$('#reset-email').validity.valid){toast('Enter a valid email address.');break}modal('Reset link sent','<p>In the live app, a password reset link is sent to your email. This presentation does not send email.</p>',btn('Back to Login','go','login'));break;
case 'driver':state.driver=Number(v);go('driver');break;
case 'new-booking':state.form={...fresh().form,vehicle:driver().types[0]};go('book');break;
case 'rebook':{const old=state.bookings.find(x=>x.id===v);state.driver=old.driver;state.form={...fresh().form,vehicle:old.vehicle,pickup:old.pickup,destinations:[...old.destinations]};go('book');break}
case 'picker':saveBookingForm();if(v!=='pickup'&&!state.form.pickup){toast('Choose your pickup location first.');break}pickerTarget=v;pickerReturn='book';pickerName=v==='pickup'?state.form.pickup:state.form.destinations[Number(v.split('-')[1])]||'';pin={x:0,y:0};go('picker');break;
case 'confirm-pin':{const name=$('#pin-name').value.trim();if(!name){toast('Enter the place name or landmark.');break}if(pickerTarget==='pickup')state.form.pickup=name;else state.form.destinations[Number(pickerTarget.split('-')[1])]=name;go(pickerReturn);break}
case 'add-stop':saveBookingForm();if(!state.form.pickup){toast('Choose your pickup location first.');break}pickerTarget='destination-'+state.form.destinations.length;pickerName='';pickerReturn='book';go('picker');break;
case 'review-booking':{saveBookingForm();const f=state.form;if(!f.pickup||!f.destinations.length){toast('Select a pickup location and at least one destination.');break}const day=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date(f.date+'T12:00:00').getDay()];const hours=f.time.split(':').map(Number),start=hours[0]+hours[1]/60;const schedule=state.schedule.find(s=>s.day===day&&s.enabled);const asHours=t=>Number(t.split(':')[0])+Number(t.split(':')[1])/60;if(!schedule||start<asHours(schedule.start)||start+f.hours>asHours(schedule.end)){toast('Choose a time within the driver’s available schedule (see Driver Profile).');break}go('confirm');break}
case 'submit-booking':{const trip={...structuredClone(state.form),id:'HMD-'+(1027+state.bookings.filter(b=>Number(b.id.slice(4))>=1027).length),driver:state.driver,status:'Pending',visited:0,extension:null};state.bookings.unshift(trip);state.selected=trip.id;notify('driver','New booking request',state.profile.name+' sent a new booking request.');state.tab='Pending';go('booked');break}
case 'details':state.selected=v;go('details');break;
case 'booking-tab':state.tab=v;go('bookings');break;
case 'cancel':state.selected=v;if(currentBooking().status!=='Pending'){toast('This booking is no longer pending.');break}state.cancelReason='Change of plans';modal('Cancellation reason',`<div>${['Change of plans','Booked by mistake','Found another driver','Other reason, please specify'].map((r,i)=>`<button class="choice ${i===0?'active':''}" ${action('cancel-reason',r)}>${r}</button>`).join('')}</div><label class="field hide" id="other-reason-field"><span>Other reason</span><textarea id="other-reason" placeholder="Please specify your reason"></textarea></label>`,btn('Keep Booking','close','','outline')+btn('Continue','submit-cancel'));break;
case 'cancel-reason':state.cancelReason=v;$$('#overlay .choice').forEach(x=>x.classList.toggle('active',x.dataset.value===v));$('#other-reason-field').classList.toggle('hide',!v.startsWith('Other'));break;
case 'submit-cancel':if(state.cancelReason.startsWith('Other')&&!$('#other-reason').value.trim()){toast('Please specify your reason.');break}if(b.status!=='Pending'){closeModal();toast('This booking is no longer pending.');break}b.status='Cancelled';notify('driver','Booking cancelled','The customer cancelled booking '+b.id+'.');state.tab='Cancelled';go('bookings');toast('Cancel request submitted.');break;
case 'accept':case 'decline':state.selected=v;if(currentBooking().status!=='Pending'){toast('This booking request is no longer pending.');break}confirmDialog(a==='accept'?'Accept booking?':'Decline booking?',a==='accept'?'Confirm that you are available for this booking.':'This request will be declined.','booking-decision',a,a==='accept'?'Accept Booking':'Decline');break;
case 'booking-decision':if(b.status!=='Pending'){closeModal();break}b.status=v==='accept'?'Accepted':'Declined';notify('customer',v==='accept'?'Booking accepted':'Booking declined',v==='accept'?'Your driver has accepted your booking.':'Your driver is unable to accept this request.');closeModal();state.tab=v==='accept'?'Upcoming':'Cancelled';go('details');break;
case 'trip-step':confirmDialog(v==='Arrived'?"Have you arrived?":v==='In Progress'?'Start service?':'Head to pickup?',v==='In Progress'?'Confirm that the customer is on board. Your booked service time will start.':v==='Arrived'?'Let your customer know that you have arrived at the pickup point.':'Let your customer know that you are on the way.','confirm-trip-step',v,v==='In Progress'?'Start Service':'Confirm');break;
case 'confirm-trip-step':b.status=v;notify('customer',v==='Arrived'?'Driver arrived':v==='In Progress'?'Service started':'Driver is on the way','Your booking '+b.id+' has been updated.');closeModal();render();break;
case 'reach':confirmDialog('Reached this destination?',`Confirm arrival at ${esc(b.destinations[b.visited])}. ${b.visited+1===b.destinations.length?'This is the last destination and will complete the booking.':'Your trip will continue to the next stop.'}`,'confirm-reach','','Confirm');break;
case 'confirm-reach':if(b.status!=='In Progress'){closeModal();break}b.visited++;if(b.visited>=b.destinations.length){b.status='Completed';notify('customer','Booking completed','You have reached your final destination. Rate your driver.');render();modal('Booking completed',`<div class="success-check" style="width:68px;height:68px">${icon('check')}</div><p>You have reached the last destination. This booking is now complete.</p>`,btn('Continue','close'));}else{notify('customer','Destination reached','Stop '+b.visited+' reached. Continuing to the next destination.');closeModal();render();toast('Destination reached. Continue to the next stop.')}break;
case 'open-extension':if(b.extension?.status==='Pending'){toast('An extension request is already pending.');break}extensionSheet();break;
case 'extension-minutes':selectedExtra=Number(v);$('#custom-minutes').value='';$$('#extension-choices .choice').forEach(x=>x.classList.toggle('active',Number(x.dataset.value)===selectedExtra));updateExtra();break;
case 'send-extension':{const custom=Number($('#custom-minutes').value),minutes=custom||selectedExtra;if(minutes<15||minutes>480){toast('Choose between 15 and 480 minutes.');break}b.extension={minutes,status:'Pending'};notify('driver','Time extension requested','The customer requested '+minutes+' more minutes.');closeModal();render();toast('Extension request sent to your driver.');break}
case 'extension-accept':case 'extension-decline':confirmDialog(a==='extension-accept'?'Accept extension?':'Decline extension?',a==='extension-accept'?`Approve ${b.extension.minutes} additional minutes for ${money(people[b.driver].rate*b.extension.minutes/60)}?`:'The original booking duration will remain unchanged.','extension-decision',a==='extension-accept'?'Accepted':'Declined',a==='extension-accept'?'Accept Extension':'Decline');break;
case 'extension-decision':if(b.extension?.status!=='Pending'){closeModal();break}b.extension.status=v;if(v==='Accepted')b.hours+=b.extension.minutes/60;notify('customer','Extension '+v.toLowerCase(),'Your driver '+v.toLowerCase()+' the service time extension.');closeModal();render();break;
case 'new-destination':newDestination();break;
case 'send-destination':if(!$('#extra-destination').value.trim()){toast('Enter the destination name.');break}b.extra=$('#extra-destination').value.trim();notify('driver','New destination request','The customer requested another stop: '+b.extra);closeModal();render();toast('Destination request sent.');break;
case 'extra-accept':b.destinations.push(b.extra);notify('customer','Destination approved','Your extra stop has been added to the route.');b.extra=null;render();break;
case 'extra-decline':b.extra=null;notify('customer','Destination declined','Your driver could not add the requested stop.');render();break;
case 'map-full':if($('#pin-name'))pickerName=$('#pin-name').value;fullMap=!fullMap;render();break;
case 'map-collapse':mapCollapsed=!mapCollapsed;$('.map-panel').classList.toggle('collapsed',mapCollapsed);$('.map-controls').style.bottom=mapCollapsed?'85px':'';break;
case 'map-type':modal('Map type',`<button class="choice ${state.mapType!=='Satellite'?'active':''}" ${action('set-map-type','Map')}>Map</button><button class="choice ${state.mapType==='Satellite'?'active':''}" ${action('set-map-type','Satellite')}>Satellite</button><p class="helper">Offline map styles are illustrative; the live app uses Google Maps.</p>`);break;
case 'set-map-type':if($('#pin-name'))pickerName=$('#pin-name').value;state.mapType=v;closeModal();render();break;
case 'locate':pin={x:0,y:0};$('.map-art').style.transform='translate(0,0)';toast('Centered on the demo location in Sikatuna.');break;
case 'filter-vehicle':state.filter.vehicle=v;render();break;case 'filter-experience':state.filter.experience=v;render();break;
case 'clear-filters':state.filter={vehicle:'All',experience:'All',area:'All'};render();break;
case 'areas':areas(v);break;
case 'choose-area':selectedAreas=state.areaKind==='driving'?(selectedAreas.includes(v)?selectedAreas.filter(x=>x!==v):[...selectedAreas,v]):[v];$('#area-choices').innerHTML=areaChoices($('#area-search').value);break;
case 'apply-area':if(state.areaKind==='driving')state.areas=[...selectedAreas];else if(state.areaKind==='best')state.bestArea=selectedAreas[0]||'Sikatuna';else state.filter.area=selectedAreas[0]||'All';closeModal();render();break;
case 'find-best':{const time=$('#best-time').value,date=$('#best-date').value,hours=parseInt($('#best-hours').value);const day=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date(date+'T12:00:00').getDay()];if(!state.schedule.some(s=>s.day===day&&s.enabled)||!time||Number(time.split(':')[0])+hours>18||Number(time.split(':')[0])<6){toast('No demo drivers available at that time. Try a weekday between 6 AM and 6 PM.');break}state.filter.vehicle=$('#best-vehicle').value;state.filter.area=state.bestArea||'Sikatuna';state.filter.experience='All';go('results');break}
case 'refresh':{const list=$('#driver-list');list.innerHTML='<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>';setTimeout(()=>{if(['popular','recommended','results'].includes(state.screen))render()},700);break}
case 'availability':state.available=!state.available;render();break;
case 'driving-vehicle':toggleArray('drivingTypes',v,people[0].types);render();break;case 'transmission':toggleArray('transmission',v,['Automatic','Manual']);render();break;case 'driving-language':toggleArray('languages',v,['English','Cebuano/Bisaya']);render();break;
case 'save-driving':if(Number($('#driving-rate').value)<=0||Number($('#driving-years').value)<0||!(state.drivingTypes||people[0].types).length){toast('Enter valid experience, hourly rate, and a vehicle type.');break}people[0].rate=Number($('#driving-rate').value);people[0].exp=Number($('#driving-years').value);people[0].types=state.drivingTypes||people[0].types;toast('Driving information saved in the demo.');break;
case 'save-schedule':{const rows=$$('[data-day]').map(input=>({day:input.dataset.day,enabled:input.checked,start:$(`[data-start="${input.dataset.day}"]`).value,end:$(`[data-end="${input.dataset.day}"]`).value}));if(rows.some(s=>s.enabled&&s.end<=s.start)){toast('End time must be later than start time.');break}state.schedule=rows;toast('Weekly schedule saved.');break}
case 'save-profile':if(!$('#profile-name').value.trim()||!$('#profile-email').validity.valid||!$('#profile-email').value){toast('Enter your name and a valid email.');break}if(state.role==='driver')people[0].name=$('#profile-name').value;else state.profile={name:$('#profile-name').value,email:$('#profile-email').value,phone:$('#profile-phone').value,address:$('#profile-address').value};if(v==='setup')go('home');else{go('profile');toast('Profile updated.')}break;
case 'review-filter':state.reviewFilter=v;render();break;
case 'rate-booking':state.selected=v;state.rating=5;go('rate');break;
case 'rating':state.reviewDraft=$('#review-text').value;state.rating=Number(v);render();break;
case 'review-tag':state.reviewDraft=$('#review-text').value;toggleArray('reviewTags',v);render();break;
case 'submit-review':{const text=$('#review-text').value.trim();if(!text){toast('Please share a short review.');break}state.reviews.unshift({name:state.profile.name,rating:state.rating,text,photo:'mika'});state.reviewFilter='See All';notify('driver','New customer review','A customer shared feedback about your service.');go('reviewed');break}
case 'notification':{const n=state.notifications[state.role][Number(v)];n.read=true;state.selected=n.id;go(n.title.includes('extension')?'trip':n.title.includes('review')?'reviews':'details');break}
case 'message-tab':$$('.tabs button').forEach(x=>x.classList.toggle('active',x.dataset.value===v));$('#message-list').style.opacity='1';if(v==='Unread')toast('Showing your demo booking conversation.');break;
case 'relationship':modal('Relationship',`<div>${['Parent','Spouse','Sibling','Family','Friend','Other'].map(r=>`<button class="choice" ${action('set-relationship',r)}>${r}</button>`).join('')}</div>`);break;
case 'set-relationship':state.emergency={name:$('#emergency-name')?.value||'Alex Reyes',phone:$('#emergency-phone')?.value||'0917 000 0456',relationship:v};closeModal();render();break;
case 'save-emergency':state.emergency={name:$('#emergency-name').value,phone:$('#emergency-phone').value,relationship:state.emergency?.relationship||'Family'};toast('Emergency contact saved.');break;
case 'emergency-preview':modal('Emergency alert preview','<p>The installed app uses your saved emergency contact. No call or message has been sent from this presentation.</p>',btn('Continue','close'));break;
case 'setting':state.settings[v]=!state.settings[v];render();break;
case 'permission':state.locationPrompted??={};state.locationPrompted[state.role]=false;go('home');break;
case 'allow-location':state.settings.location=true;closeModal();toast('Location access enabled in the demo.');break;
case 'language':state.language=v;render();toast('Demo language preference saved.');break;
case 'change-password':if(!$('#old-password').value||$('#new-password').value.length<6||$('#new-password').value!==$('#confirm-password').value){toast('Enter the current password and matching new passwords of at least 6 characters.');break}modal('Password updated','<p>Your sample password change is complete. Real account credentials are unchanged.</p>');break;
case 'send-support':if(!$('#support-message').value.trim()){toast('Please describe your concern.');break}modal('Message submitted','<p>Your support request is demonstrated here. No email or support ticket was sent.</p>',btn('Continue','go','help'));break;
case 'logout':confirmDialog('Are you sure you want to logout?','You can sign in again to access your account.','logout-confirm','','Logout');break;
case 'logout-confirm':go('welcome');break;
case 'delete-account':if($('#delete-text').value!=='DELETE'){toast('Type DELETE to confirm.');break}confirmDialog('Delete demo account?','This only resets the sample data in this presentation.','reset','','Delete');break;
case 'offline-retry':closeModal();setTimeout(()=>{if(offline)offlineDialog()},300);break;
case 'offline-cancel':offline=false;closeModal();modal('App closed','<p>On the phone, Cancel exits the app. Reopen the presentation to continue.</p>',btn('Reopen Demo','go','home'));break;
}}
function updateExtra(){const b=currentBooking();const minutes=Number($('#custom-minutes')?.value)||selectedExtra;$('#extra-fee').textContent=money(people[b.driver].rate*minutes/60);$('#extra-total').textContent=(b.hours+minutes/60)+' hours'}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();perform(el.dataset.action,el.dataset.value||'',el)});
document.addEventListener('input',e=>{if(e.target.id==='screen-search')directory();if(e.target.id==='area-search')$('#area-choices').innerHTML=areaChoices(e.target.value);if(e.target.id==='driver-search'){const q=e.target.value.toLowerCase();$$('#driver-list .driver-card').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'':'none')}if(e.target.id==='custom-minutes')updateExtra();if(e.target.id==='book-hours'){saveBookingForm();$('#fee').textContent=money(driver().rate*state.form.hours);$('#hours-caption').textContent=state.form.hours}});
document.addEventListener('change',e=>{if(e.target.id==='compact-role')setRole(e.target.value);if(e.target.id==='compact-screen')jump(e.target.value)});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='chat-form'){const text=$('#chat-text').value.trim();if(!text)return;state.messages.push({role:state.role,text});notify(state.role==='customer'?'driver':'customer','New message',text);render();$('#chat-text').focus();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay').children.length){const focusables=$$('#overlay button, #overlay input, #overlay textarea, #overlay select').filter(x=>x.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
window.addEventListener('resize',resizePhone);$$('[data-asset]').forEach(x=>x.src=art(x.dataset.asset));render();
